		if err != nil {
			t.Fatal(err)
		}
		t.Log("### " + n)
		seen := map[string]bool{}
		for _, l := range strings.Split(string(raw), "\n") {
			if re.MatchString(l) {
				k := strings.TrimSpace(l)
				if i := strings.Index(k, " ("); strings.HasPrefix(k, "--- FAIL") && i > 0 {
					k = k[:i]
				}
				if strings.Contains(k, "belongs to") {
					k = "env: belongs to another user"
				}
				if !seen[k] {
					seen[k] = true
					t.Log(k)
				}
			}
		}
	}
}
EOF
